INSERT INTO database_rows (row_id, database_id, properties_json, created_time, last_edited_time, archived) VALUES ('row_hmblg_0213', 'db_finance_ledger', '{"date": "2025-12-03", "amount_minor": 74747, "kind": "facility_charge", "note": "facility charge after plan discount, patient responsibility", "constraint": "authorized cap applies before execution", "source": "provider statement", "status": "posted"}', '2025-12-03T18:22:00Z', '2025-12-04T20:00:00Z', 0);
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_hmblg_0000', NULL, 'pg_hmblg_000', 'paragraph', '{"text": "The 2026 limits are $4,400 self-only and $8,750 family. My coverage tier determines which applies, and employer contributions count toward the same limit."}', 0, 0, 0, '2026-01-20T09:00:00Z', '2026-05-29T09:30:00Z');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_hmblg_0001', NULL, 'pg_hmblg_000', 'paragraph', '{"text": "Contributions to date include both payroll deductions and the employer seed. The remaining room is the limit minus that combined total, not minus my payroll deductions alone."}', 0, 0, 1, '2026-01-20T10:00:00Z', '2026-05-29T10:30:00Z');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_hmblg_0002', NULL, 'pg_hmblg_000', 'paragraph', '{"text": "Excess contributions are subject to a 6% excise tax for each year the excess remains in the account. Removing an excess before the tax deadline avoids the penalty."}', 0, 0, 2, '2026-01-20T11:00:00Z', '2026-05-29T11:30:00Z');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_hmblg_0003', NULL, 'pg_hmblg_000', 'paragraph', '{"text": "Open question for the custodian: confirm the employer portion posted so far."}', 0, 0, 3, '2026-01-20T12:00:00Z', '2026-05-29T12:30:00Z');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_hmblg_0004', NULL, 'pg_hmblg_100', 'to_do', '{"text": "Checked the tool state rather than the mailed figure; they differed by $628.00.", "checked": true}', 0, 0, 0, '2026-01-20T21:10:00Z', '2026-05-29T21:40:00Z');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_hmblg_0005', NULL, 'pg_hmblg_100', 'paragraph', '{"text": "Waiting on written confirmation before paying anything.", "checked": true}', 0, 0, 1, '2026-01-20T21:11:00Z', '2026-05-29T21:41:00Z');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_hmblg_0006', NULL, 'pg_hmblg_100', 'paragraph', '{"text": "Called and left a message; reference distribution 70418. Left open on purpose until the refund posts.", "checked": false}', 0, 0, 2, '2026-01-20T21:12:00Z', '2026-05-29T21:42:00Z');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_hmblg_0007', NULL, 'pg_hmblg_001', 'bulleted_list_item', '{"text": "The facility was in network but the surgical assistant was not, which is how the balance bill appeared on an otherwise in-network procedure."}', 0, 0, 0, '2025-11-17T09:00:00Z', '2026-05-21T09:30:00Z');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_hmblg_0008', NULL, 'pg_hmblg_001', 'paragraph', '{"text": "Federal surprise-billing protections can limit patient responsibility for ancillary services delivered at an in-network facility."}', 0, 0, 1, '2025-11-17T10:00:00Z', '2026-05-21T10:30:00Z');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_hmblg_0009', NULL, 'pg_hmblg_001', 'bulleted_list_item', '{"text": "The practice agreed to hold the account while the plan reviews. Paying now would waive leverage and complicate any refund."}', 0, 0, 2, '2025-11-17T11:00:00Z', '2026-05-21T11:30:00Z');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_hmblg_0010', NULL, 'pg_hmblg_001', 'paragraph', '{"text": "Next step: get the review reference number in writing and diary the hold expiration."}', 0, 0, 3, '2025-11-17T12:00:00Z', '2026-05-21T12:30:00Z');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_hmblg_0011', NULL, 'pg_hmblg_101', 'to_do', '{"text": "Waiting on written confirmation before paying anything.", "checked": true}', 0, 0, 0, '2025-11-17T21:10:00Z', '2026-05-21T21:40:00Z');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_hmblg_0012', NULL, 'pg_hmblg_101', 'paragraph', '{"text": "Called and left a message; reference claim 2026418702. No change to the reserve floor either way.", "checked": true}', 0, 0, 1, '2025-11-17T21:11:00Z', '2026-05-21T21:41:00Z');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_hmblg_0013', NULL, 'pg_hmblg_101', 'to_do', '{"text": "Checked the tool state rather than the mailed figure; they differed by $12.40. Left open on purpose until the refund posts.", "checked": true}', 0, 0, 2, '2025-11-17T21:12:00Z', '2026-05-21T21:42:00Z');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_hmblg_0014', NULL, 'pg_hmblg_002', 'paragraph', '{"text": "The individual deductible is $3,400 and the out-of-pocket maximum is $8,200. After the deductible, covered services run at coinsurance."}', 0, 0, 0, '2025-12-15T09:00:00Z', '2026-05-21T09:30:00Z');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_hmblg_0015', NULL, 'pg_hmblg_002', 'paragraph', '{"text": "Only allowed amounts count toward these totals; balance-billed amounts from out-of-network providers generally do not."}', 0, 0, 1, '2025-12-15T10:00:00Z', '2026-05-21T10:30:00Z');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_hmblg_0016', NULL, 'pg_hmblg_002', 'paragraph', '{"text": "Tracking progress matters because once the out-of-pocket maximum is met, further covered services cost nothing, which changes the payment sequencing."}', 0, 0, 2, '2025-12-15T11:00:00Z', '2026-05-21T11:30:00Z');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_hmblg_0017', NULL, 'pg_hmblg_102', 'paragraph', '{"text": "Called and left a message; reference distribution 70418. Superseded an earlier note that used the pre-reprocessing amount.", "checked": true}', 0, 0, 0, '2025-12-15T21:10:00Z', '2026-05-21T21:40:00Z');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_hmblg_0018', NULL, 'pg_hmblg_102', 'paragraph', '{"text": "Filed the paperwork on 2026-06-03. Attached the itemized page to the HSA folder.", "checked": false}', 0, 0, 1, '2025-12-15T21:11:00Z', '2026-05-21T21:41:00Z');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_hmblg_0019', NULL, 'pg_hmblg_003', 'paragraph', '{"text": "The hospital plan is interest-free with no credit check. The card balance accrues at the purchase APR."}', 0, 0, 0, '2025-12-25T09:00:00Z', '2026-06-13T09:30:00Z');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_hmblg_0020', NULL, 'pg_hmblg_003', 'paragraph', '{"text": "Paying the interest-free balance early while carrying a revolving card balance costs money for no benefit."}', 0, 0, 1, '2025-12-25T10:00:00Z', '2026-06-13T10:30:00Z');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_hmblg_0021', NULL, 'pg_hmblg_003', 'paragraph', '{"text": "CFPB materials note that paying only the card minimum can take years and cost substantially more in interest."}', 0, 0, 2, '2025-12-25T11:00:00Z', '2026-06-13T11:30:00Z');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_hmblg_0022', NULL, 'pg_hmblg_003', 'bulleted_list_item', '{"text": "Sequencing: keep the plan installments current, direct spare cash flow at the card."}', 0, 0, 3, '2025-12-25T12:00:00Z', '2026-06-13T12:30:00Z');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_hmblg_0023', NULL, 'pg_hmblg_103', 'to_do', '{"text": "Filed the paperwork on 2026-06-02. Superseded an earlier note that used the pre-reprocessing amount.", "checked": true}', 0, 0, 0, '2025-12-25T21:10:00Z', '2026-06-13T21:40:00Z');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_hmblg_0024', NULL, 'pg_hmblg_103', 'paragraph', '{"text": "Rejected the $10,000 contribution pitch and recorded why so it does not resurface. Attached the itemized page to the HSA folder.", "checked": false}', 0, 0, 1, '2025-12-25T21:11:00Z', '2026-06-13T21:41:00Z');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_hmblg_0025', NULL, 'pg_hmblg_004', 'bulleted_list_item', '{"text": "Qualified expenses are defined in IRS Publication 502. Credit-card slips without service detail are not sufficient documentation."}', 0, 0, 0, '2026-02-08T09:00:00Z', '2026-06-03T09:30:00Z');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_hmblg_0026', NULL, 'pg_hmblg_004', 'paragraph', '{"text": "There is no deadline to reimburse yourself for an expense incurred after the account was established, provided records are kept."}', 0, 0, 1, '2026-02-08T10:00:00Z', '2026-06-03T10:30:00Z');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_hmblg_0027', NULL, 'pg_hmblg_004', 'bulleted_list_item', '{"text": "Unsubstantiated distributions may be reported as taxable and can carry an additional 20% tax."}', 0, 0, 2, '2026-02-08T11:00:00Z', '2026-06-03T11:30:00Z');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_hmblg_0028', NULL, 'pg_hmblg_004', 'paragraph', '{"text": "Every itemized receipt and matching EOB goes in the HSA folder as it arrives."}', 0, 0, 3, '2026-02-08T12:00:00Z', '2026-06-03T12:30:00Z');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_hmblg_0029', NULL, 'pg_hmblg_104', 'paragraph', '{"text": "Waiting on written confirmation before paying anything.", "checked": true}', 0, 0, 0, '2026-02-08T21:10:00Z', '2026-06-03T21:40:00Z');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_hmblg_0030', NULL, 'pg_hmblg_104', 'to_do', '{"text": "Checked the tool state rather than the mailed figure; they differed by $153.50. Cross-checked against the EOB before recording.", "checked": true}', 0, 0, 1, '2026-02-08T21:11:00Z', '2026-06-03T21:41:00Z');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_hmblg_0031', NULL, 'pg_hmblg_005', 'bulleted_list_item', '{"text": "The \"$10,000 HSA\" marketing figure exceeds the statutory limit for any coverage tier and is not a contribution target."}', 0, 0, 0, '2026-01-23T09:00:00Z', '2026-05-25T09:30:00Z');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_hmblg_0032', NULL, 'pg_hmblg_005', 'paragraph', '{"text": "\"Any bill qualifies\" is a reader-discussion claim, not guidance; qualification follows Publication 502."}', 0, 0, 1, '2026-01-23T10:00:00Z', '2026-05-25T10:30:00Z');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_hmblg_0033', NULL, 'pg_hmblg_005', 'paragraph', '{"text": "\"Skip receipts\" estimator apps do not produce substantiation, and the account holder remains responsible for records."}', 0, 0, 2, '2026-01-23T11:00:00Z', '2026-05-25T11:30:00Z');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_hmblg_0034', NULL, 'pg_hmblg_005', 'bulleted_list_item', '{"text": "Debt-settlement solicitations charge a percentage of the reduction and can leave accounts unpaid during negotiation. The hospital already offers interest-free terms."}', 0, 0, 3, '2026-01-23T12:00:00Z', '2026-05-25T12:30:00Z');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_hmblg_0035', NULL, 'pg_hmblg_105', 'paragraph', '{"text": "Rejected the $10,000 contribution pitch and recorded why so it does not resurface. No change to the reserve floor either way.", "checked": true}', 0, 0, 0, '2026-01-23T21:10:00Z', '2026-05-25T21:40:00Z');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_hmblg_0036', NULL, 'pg_hmblg_105', 'to_do', '{"text": "Waiting on written confirmation before paying anything. Superseded an earlier note that used the pre-reprocessing amount.", "checked": false}', 0, 0, 1, '2026-01-23T21:11:00Z', '2026-05-25T21:41:00Z');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_hmblg_0037', NULL, 'pg_hmblg_105', 'to_do', '{"text": "Called and left a message; reference distribution 70418. Cross-checked against the EOB before recording.", "checked": false}', 0, 0, 2, '2026-01-23T21:12:00Z', '2026-05-25T21:42:00Z');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_hmblg_0038', NULL, 'pg_hmblg_105', 'paragraph', '{"text": "Waiting on written confirmation before paying anything. Attached the itemized page to the HSA folder.", "checked": false}', 0, 0, 3, '2026-01-23T21:13:00Z', '2026-05-25T21:43:00Z');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_hmblg_0039', NULL, 'pg_hmblg_006', 'bulleted_list_item', '{"text": "The reserve exists to cover the remaining out-of-pocket maximum in a bad year, not to smooth ordinary bills."}', 0, 0, 0, '2026-01-28T09:00:00Z', '2026-06-04T09:30:00Z');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_hmblg_0040', NULL, 'pg_hmblg_006', 'paragraph', '{"text": "It stays out of every option under consideration: the plan installments, the card payoff, and the disputed balance."}', 0, 0, 1, '2026-01-28T10:00:00Z', '2026-06-04T10:30:00Z');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_hmblg_0041', NULL, 'pg_hmblg_006', 'paragraph', '{"text": "If a plan only works by drawing this down, the plan is wrong, not the floor."}', 0, 0, 2, '2026-01-28T11:00:00Z', '2026-06-04T11:30:00Z');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_hmblg_0042', NULL, 'pg_hmblg_106', 'to_do', '{"text": "Called and left a message; reference distribution 70418. Left open on purpose until the refund posts.", "checked": true}', 0, 0, 0, '2026-01-28T21:10:00Z', '2026-06-04T21:40:00Z');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_hmblg_0043', NULL, 'pg_hmblg_106', 'paragraph', '{"text": "Filed the paperwork on 2026-05-27.", "checked": false}', 0, 0, 1, '2026-01-28T21:11:00Z', '2026-06-04T21:41:00Z');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_hmblg_0044', NULL, 'pg_hmblg_106', 'paragraph', '{"text": "Waiting on written confirmation before paying anything.", "checked": false}', 0, 0, 2, '2026-01-28T21:12:00Z', '2026-06-04T21:42:00Z');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_hmblg_0045', NULL, 'pg_hmblg_007', 'bulleted_list_item', '{"text": "Fixed obligations cluster at the start of the month: rent, premium, plan installment."}', 0, 0, 0, '2026-01-30T09:00:00Z', '2026-06-05T09:30:00Z');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_hmblg_0046', NULL, 'pg_hmblg_007', 'paragraph', '{"text": "The summer session stipend pays across two cycles and changes the mid-July picture."}', 0, 0, 1, '2026-01-30T10:00:00Z', '2026-06-05T10:30:00Z');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_hmblg_0047', NULL, 'pg_hmblg_007', 'paragraph', '{"text": "The HSA investment sleeve is long-term; near-term qualified expenses should come from the cash side, not by selling the sleeve."}', 0, 0, 2, '2026-01-30T11:00:00Z', '2026-06-05T11:30:00Z');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_hmblg_0048', NULL, 'pg_hmblg_107', 'paragraph', '{"text": "Checked the tool state rather than the mailed figure; they differed by $628.00.", "checked": false}', 0, 0, 0, '2026-01-30T21:10:00Z', '2026-06-05T21:40:00Z');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_hmblg_0049', NULL, 'pg_hmblg_107', 'paragraph', '{"text": "Checked the tool state rather than the mailed figure; they differed by $628.00. Attached the itemized page to the HSA folder.", "checked": true}', 0, 0, 1, '2026-01-30T21:11:00Z', '2026-06-05T21:41:00Z');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_hmblg_0050', NULL, 'pg_hmblg_008', 'bulleted_list_item', '{"text": "When a claim reprocesses at the in-network rate, an amount already paid may exceed the corrected responsibility."}', 0, 0, 0, '2026-01-01T09:00:00Z', '2026-05-22T09:30:00Z');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_hmblg_0051', NULL, 'pg_hmblg_008', 'paragraph', '{"text": "The provider must refund the difference; a corrected statement should follow."}', 0, 0, 1, '2026-01-01T10:00:00Z', '2026-05-22T10:30:00Z');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_hmblg_0052', NULL, 'pg_hmblg_008', 'bulleted_list_item', '{"text": "Track which payments were made before reprocessing so the refund can be matched."}', 0, 0, 2, '2026-01-01T11:00:00Z', '2026-05-22T11:30:00Z');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_hmblg_0053', NULL, 'pg_hmblg_108', 'paragraph', '{"text": "Checked the tool state rather than the mailed figure; they differed by $12.40.", "checked": false}', 0, 0, 0, '2026-01-01T21:10:00Z', '2026-05-22T21:40:00Z');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_hmblg_0054', NULL, 'pg_hmblg_108', 'to_do', '{"text": "Checked the tool state rather than the mailed figure; they differed by $12.40.", "checked": false}', 0, 0, 1, '2026-01-01T21:11:00Z', '2026-05-22T21:41:00Z');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_hmblg_0055', NULL, 'pg_hmblg_108', 'paragraph', '{"text": "Next step is mine; do it after the next payroll deposit.", "checked": true}', 0, 0, 2, '2026-01-01T21:12:00Z', '2026-05-22T21:42:00Z');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_hmblg_0056', NULL, 'pg_hmblg_009', 'paragraph', '{"text": "The imaging coinsurance appeal is open; the autopay for that provider is paused while it runs."}', 0, 0, 0, '2026-01-10T09:00:00Z', '2026-06-11T09:30:00Z');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_hmblg_0057', NULL, 'pg_hmblg_009', 'paragraph', '{"text": "Internal appeals have a filing deadline; missing it forfeits the argument regardless of merit."}', 0, 0, 1, '2026-01-10T10:00:00Z', '2026-06-11T10:30:00Z');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_hmblg_0058', NULL, 'pg_hmblg_009', 'paragraph', '{"text": "Nothing in an open appeal should be paid down early."}', 0, 0, 2, '2026-01-10T11:00:00Z', '2026-06-11T11:30:00Z');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_hmblg_0059', NULL, 'pg_hmblg_109', 'to_do', '{"text": "Next step is mine; do it after the next payroll deposit. Superseded an earlier note that used the pre-reprocessing amount.", "checked": false}', 0, 0, 0, '2026-01-10T21:10:00Z', '2026-06-11T21:40:00Z');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_hmblg_0060', NULL, 'pg_hmblg_109', 'paragraph', '{"text": "Rejected the $10,000 contribution pitch and recorded why so it does not resurface. Attached the itemized page to the HSA folder.", "checked": true}', 0, 0, 1, '2026-01-10T21:11:00Z', '2026-06-11T21:41:00Z');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_hmblg_0061', NULL, 'pg_hmblg_109', 'paragraph', '{"text": "Next step is mine; do it after the next payroll deposit. Revisit once the plan review closes.", "checked": true}', 0, 0, 2, '2026-01-10T21:12:00Z', '2026-06-11T21:42:00Z');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_hmblg_0062', NULL, 'pg_hmblg_010', 'paragraph', '{"text": "HDHP and HSA elections are made together during open enrollment."}', 0, 0, 0, '2025-12-11T09:00:00Z', '2026-06-11T09:30:00Z');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_hmblg_0063', NULL, 'pg_hmblg_010', 'paragraph', '{"text": "A tier change mid-year prorates the annual limit by month unless the last-month rule applies, which carries a testing-period requirement."}', 0, 0, 1, '2025-12-11T10:00:00Z', '2026-06-11T10:30:00Z');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_hmblg_0064', NULL, 'pg_hmblg_010', 'paragraph', '{"text": "Confirming the tier on file with HR is a prerequisite to any lump-sum contribution."}', 0, 0, 2, '2025-12-11T11:00:00Z', '2026-06-11T11:30:00Z');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_hmblg_0065', NULL, 'pg_hmblg_110', 'to_do', '{"text": "Filed the paperwork on 2026-05-16. Left open on purpose until the refund posts.", "checked": true}', 0, 0, 0, '2025-12-11T21:10:00Z', '2026-06-11T21:40:00Z');
