INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_hmblg_0067', NULL, 'pg_hmblg_110', 'paragraph', '{"text": "Checked the tool state rather than the mailed figure; they differed by $628.00. Left open on purpose until the refund posts.", "checked": true}', 0, 0, 2, '2025-12-11T21:12:00Z', '2026-06-11T21:42:00Z');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_hmblg_0068', NULL, 'pg_hmblg_110', 'paragraph', '{"text": "Called and left a message; reference distribution 70418.", "checked": false}', 0, 0, 3, '2025-12-11T21:13:00Z', '2026-06-11T21:43:00Z');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_hmblg_0069', NULL, 'pg_hmblg_011', 'bulleted_list_item', '{"text": "Rent has a five-day grace period; online payments post the next business day."}', 0, 0, 0, '2026-01-30T09:00:00Z', '2026-06-04T09:30:00Z');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_hmblg_0070', NULL, 'pg_hmblg_011', 'paragraph', '{"text": "The electric plan is time-of-use with weekday-afternoon on-peak hours; summer cooling load dominates."}', 0, 0, 1, '2026-01-30T10:00:00Z', '2026-06-04T10:30:00Z');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_hmblg_0071', NULL, 'pg_hmblg_011', 'paragraph', '{"text": "Budget billing would level payments but does not reduce the total."}', 0, 0, 2, '2026-01-30T11:00:00Z', '2026-06-04T11:30:00Z');
